import java.util.Scanner;

public class SumUntilZero {
    public static void main(String[] args) {
        Scanner console = new Scanner(System.in);
        int sum = 0, num;

        while (true) {
            System.out.println("Type 0 to end program. A negative number is invalid.");
            System.out.print("Enter a number to add: ");
            num = console.nextInt();

            if (num == 0) {
                System.out.println("You entered 0. End of program. Thank you!");
                break;
            }

            sum = sum + num;
            System.out.println("The sum of entered numbers is: " + sum);
        }

        console.close();
    }
}

import java.util.Scanner;

public class SumSkippingNegatives {
    public static void main(String[] args) {
        Scanner console = new Scanner(System.in);
        int sum = 0, num;

        while (true) {
            System.out.println("Type 0 to end program. A negative number is invalid.");
            System.out.print("Enter a number to add: ");
            num = console.nextInt();

            if (num == 0) {
                System.out.println("You entered 0. End of program. Thank you!");
                break;
            }
            else if (num < 0) {
                System.out.println("You entered a negative number.");
                continue;
            }

            sum = sum + num;
            System.out.println("The sum of entered numbers is: " + sum);
        }

        console.close();
    }
}

